def cantor_numbering(n):
    if n == 1:
        return "1/1"
    elif n % 2 == 0:
        denom = cantor_numbering(n // 2)
        return f"1/{denom}"
    else:
        numer = cantor_numbering((n + 1) // 2)
        denom = cantor_numbering(n // 2)
        return f"{numer}/{denom}"
