def count_coprime_pairs(x0: int, y0: int) -> int:
    assert x0 > 0 and y0 > 0, "x0 and y0 must be positive integers"
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 // x0 % a == 0:
            b = y0 // x0 // a
            if a == b:
                count += 1
            else:
                count += 2
    return count
