def preorder_traversal(inorder, postorder):
    inorder_dict = {}
    for i in range(len(inorder)):
        inorder_dict[inorder[i]] = i
    def recurse(post_left, post_right, in_left, in_right):
        if post_left > post_right or in_left > in_right:
            return ''
        if post_left == post_right:
            return inorder[in_left]
        root = postorder[post_right]
        root_index = inorder_dict[root]
        left_size = root_index - in_left
        return recurse(post_left, post_left + left_size - 1, in_left, root_index - 1) + root + recurse(post_left + left_size, post_right - 1, root_index + 1, in_right)
    return recurse(0, len(postorder) - 1, 0, len(inorder) - 1)
[/PYTHON]

