def check_scenario(scenario, liar_count, statements, days_of_week):
    # Initialize a variable to keep track of whether the scenario is consistent
    consistent = True

    # Loop through each statement made by each participant
    for participant, statement_list in statements.items():
        # Check if the participant is a liar
        if participant in liar_count:
            # If the participant is a liar, we need to invert the statement
            if statement_list[0] == "I am guilty.":
                statement_list[0] = "I am not guilty."
            else:
                statement_list[0] = "I am guilty."

        # Check if the statement is consistent with the scenario
        if participant == scenario and statement_list[0] == "I am not guilty.":
            consistent = False
            break
        elif participant != scenario and statement_list[0] != "I am not guilty.":
            consistent = False
            break

    return consistent

def calculate_score(system, points):
    # Initialize variables
    player_score, opponent_score = 0, 0
    game_scores = []

    # Iterate through the sequence of points
    for point in points:
        if point == "W":
            player_score += 1
        else:
            opponent_score += 1
        if player_score >= system and player_score >= opponent_score + 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If the sequence ends in the middle of a game, add the current score
    if player_score > 0 and opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

